mapper.select:
SELECT p.id, p.name, c.name as customerName, p.address, p.area, p.status, p.status as statusText, p.progress as progressPercent, pm.role as myRole, p.updated_at as lastUpdateTime FROM project_members pm INNER JOIN projects p ON pm.project_id = p.id AND p.deleted_at IS NULL LEFT JOIN customers c ON p.customer_id = c.id WHERE pm.user_id = #{userId} AND pm.is_active = 1
AND p.status COLLATE utf8mb4_unicode_ci IN
#{status}
ORDER BY (SELECT COALESCE(dict_sort, 999) FROM sys_dict_data WHERE dict_type = 'decoration_status_project_order' AND dict_value = p.status COLLATE utf8mb4_unicode_ci LIMIT 1) ASC, p.updated_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM project_members pm INNER JOIN projects p ON pm.project_id = p.id AND p.deleted_at IS NULL WHERE pm.user_id = #{userId} AND pm.is_active = 1
AND p.status COLLATE utf8mb4_unicode_ci IN
#{status}
